import {
  apiGetHelper,
  apiPostHelper,
  apiPostFormDataHelper,
} from '../commonUtills/helperAxios';

const API_URL = process.env.REACT_APP_SCHOOL_BACKEND_URL;

export const fetchClassSubjects = async (obj) => {
  let finalRes = {};
  const headers = {
    headers: {
      'Content-Type': 'application/json',
    },
    params: obj,
  };
  await apiGetHelper(`${API_URL}/common/fetch-class-subjects`, headers).then(
    (response) => {
      finalRes = response.data;
    }
  );
  return Promise.resolve(finalRes);
};

export const uploadHomeworkImage = async (data) => {
  let finalRes = {};
  const headers = {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  };
  await apiPostFormDataHelper(`${API_URL}/files/upload`, data, headers).then(
    (response) => {
      finalRes = response.data;
    }
  );
  return Promise.resolve(finalRes);
};

export const createHomeworkUpload = async (obj) => {
  let finalRes = {};
  const headers = {
    headers: {
      'Content-Type': 'application/json',
    },
  };
  await apiPostHelper(
    `${API_URL}/homework-upload/create`,
    obj,
    headers
  ).then((response) => {
    finalRes = response.data;
  });
  return Promise.resolve(finalRes);
};
